(function(){"use strict";app.factory("tiempoCreditoService",function(t){const e=t.get("mainService"),n="Config/TiempoCredito/",i={get:function(t){return e.getData("get",n+"?json="+JSON.stringify(t),null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let e=JSON.parse(t.payload)||[];return e}})},save:function(t){return e.getData("post",`${n}?json=${JSON.stringify(t)}`,null,!0)},update:function(t,i){return e.getData("put",`${n}${t}?json=${JSON.stringify(i)}`,null,!0)},delete:function(t){return e.getData("delete",n+t,null,!0)}};return i})})(window.angular);